#!/usr/bin/env node
/**
 * THE VENDORED VELOCITY SDK, AS src/lib/velocityTrade.js USES IT.
 * ---------------------------------------------------------------------------
 * The tab does not import @velocity-exchange/sdk through the bundler — it loads
 * a prebuilt ESM bundle (public/vendor/velocity-sdk.js, generated by
 * scripts/vendor-velocity.mjs at `prebuild`) so the ~2700-module SDK never
 * enters the Rollup graph. That indirection means a version bump can rename a
 * method and the UI would only find out when a user taps Buy.
 *
 * So this probe imports the SHIPPED bundle and pins everything the trade module
 * calls against it: the mainnet-beta config the module asserts on, the client
 * methods it invokes, the Anchor-style enum shapes it puts in OrderParams, the
 * address lookup tables it compiles transactions with, and the PDA/ATA
 * derivations that must be Velocity's and not Drift's.
 *
 * It does NOT place an order: that needs a live (or bankrun) cluster and a real
 * signer, which CI has neither of. What it proves is that every symbol and
 * constant the order path depends on exists, in the shape the code expects.
 *
 *   node test/futures-velocity-trade-probe.mjs
 */
import { readFileSync, existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import { webcrypto } from 'node:crypto';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const BUNDLE = join(ROOT, 'public', 'vendor', 'velocity-sdk.js');

const rows = [];
const t = (name, ok, extra = '') => { rows.push([name, Boolean(ok)]); console.log(`${ok ? '✓' : '✗'} ${name}${ok || !extra ? '' : ` — ${String(extra).slice(0, 160)}`}`); };

t('the prebuilt vendor bundle exists (npm run vendor:velocity / prebuild)', existsSync(BUNDLE), BUNDLE);
if (!existsSync(BUNDLE)) { process.exitCode = 1; process.exit(1); }
t('the bundle is a real prebundle, not a stub', readFileSync(BUNDLE, 'utf8').length > 500_000);

/* The trade module reads its symbols off this exact module. */
const sdk = await import(BUNDLE);
const NEEDED = [
  'initialize', 'getConfig', 'VelocityClient', 'VELOCITY_PROGRAM_ID',
  'getUserAccountPublicKey', 'getUserStatsAccountPublicKey',
  'BN', 'Connection', 'PublicKey', 'VersionedTransaction', 'TransactionMessage', 'ComputeBudgetProgram',
  'getAssociatedTokenAddressSync',
  'OrderType', 'MarketType', 'PositionDirection', 'PostOnlyParams', 'OrderTriggerCondition'
];
t('every symbol src/lib/velocityTrade.js imports is exported', NEEDED.every((k) => k in sdk),
  NEEDED.filter((k) => !(k in sdk)).join(', ') || `${Object.keys(sdk).length} exports`);

/* ── the config the module refuses to trade without ──────────────────────── */
/* `getConfig()` is module state that DEFAULTS TO DEVNET: same program id, a
   dUSDT quote mint and devnet market indices. The module calls initialize()
   and then asserts, because building a "mainnet" order from the devnet preset
   would still broadcast. */
const devnetDefault = sdk.getConfig();
t('the SDK really does default to devnet (why initialize() is mandatory)', devnetDefault?.ENV === 'devnet', devnetDefault?.ENV);
t('devnet and mainnet share one program id (a wrong config fails silently)',
  sdk.VELOCITY_PROGRAM_ID === 'vELoC1audYbSYVRXn1vPaV8Axoa9oU6BYmNGZZBDZ1P');

sdk.initialize({ env: 'mainnet-beta' });
const cfg = sdk.getConfig();
t('initialize({env:"mainnet-beta"}) switches the active config', cfg?.ENV === 'mainnet-beta', cfg?.ENV);
t("mainnet-beta's quote asset is USDT — the module's pinned mint",
  cfg?.QUOTE_MINT_ADDRESS === 'Es9vMFrzaCERmJfrF4H2FYD4KCoNkY11McCe8BenwNYB', cfg?.QUOTE_MINT_ADDRESS);
const perps = Object.fromEntries((cfg?.PERP_MARKETS || []).map((m) => [m.symbol, m.marketIndex]));
t('the four perps match the offline index table in src/lib/velocityMarkets.js',
  perps['SOL-PERP'] === 0 && perps['BTC-PERP'] === 1 && perps['ETH-PERP'] === 2 && perps['HYPE-PERP'] === 3,
  JSON.stringify(perps));
const spots = Object.fromEntries((cfg?.SPOT_MARKETS || []).map((m) => [m.symbol, m.marketIndex]));
t('USDT is spot market 0 — the index the deposit instruction uses', spots.USDT === 0, JSON.stringify(spots));
const luts = Array.isArray(cfg?.MARKET_LOOKUP_TABLES) ? cfg.MARKET_LOOKUP_TABLES : [];
t('the config carries the address lookup tables the tx compiler needs',
  luts.length > 0 && luts.every((x) => /^[1-9A-HJ-NP-Za-km-z]{32,44}$/.test(String(x))), JSON.stringify(luts));

/* ── the client methods, with the exact shapes the module calls ──────────── */
const proto = sdk.VelocityClient?.prototype || {};
for (const m of ['subscribe', 'unsubscribe', 'getInitializeUserAccountIxs', 'getDepositInstruction', 'getPlacePerpOrderIx', 'getCancelOrdersIx', 'getUser', 'getQuoteAssetTokenAmount']) {
  t(`VelocityClient.${m} exists`, typeof proto[m] === 'function');
}

/* ── the Anchor-style enums that go into OrderParams ─────────────────────── */
const eq = (a, b) => JSON.stringify(a) === JSON.stringify(b);
t('OrderType.MARKET / TRIGGER_MARKET are Anchor enums, not strings',
  eq(sdk.OrderType.MARKET, { market: {} }) && eq(sdk.OrderType.TRIGGER_MARKET, { triggerMarket: {} }),
  `${JSON.stringify(sdk.OrderType.MARKET)}/${JSON.stringify(sdk.OrderType.TRIGGER_MARKET)}`);
t('MarketType.PERP and both directions are Anchor enums',
  eq(sdk.MarketType.PERP, { perp: {} }) && 'LONG' in sdk.PositionDirection && 'SHORT' in sdk.PositionDirection
    && eq(sdk.PositionDirection.LONG, { long: {} }) && eq(sdk.PositionDirection.SHORT, { short: {} }));
t('PostOnlyParams.NONE and both trigger conditions are Anchor enums',
  eq(sdk.PostOnlyParams.NONE, { none: {} }) && eq(sdk.OrderTriggerCondition.ABOVE, { above: {} })
    && eq(sdk.OrderTriggerCondition.BELOW, { below: {} }));

/* ── address derivation must be Velocity's ───────────────────────────────── */
if (!globalThis.crypto?.subtle) Object.defineProperty(globalThis, 'crypto', { value: webcrypto, configurable: true });
const { Keypair } = await import('@solana/web3.js'); // the bundle does not export Keypair
const owner = Keypair.generate().publicKey;
const userPda = await sdk.getUserAccountPublicKey(new sdk.PublicKey(sdk.VELOCITY_PROGRAM_ID), owner, 0);
const statsPda = sdk.getUserStatsAccountPublicKey(new sdk.PublicKey(sdk.VELOCITY_PROGRAM_ID), owner);
const quoteAta = sdk.getAssociatedTokenAddressSync(new sdk.PublicKey(cfg.QUOTE_MINT_ADDRESS), owner);
t('the user, userStats and USDT-ATA addresses derive for a real wallet',
  sdk.PublicKey.isOnCurve ? Boolean(userPda) && Boolean(statsPda) && Boolean(quoteAta) : true,
  `${userPda?.toString()} / ${statsPda?.toString()} / ${quoteAta?.toString()}`);
/* Seeds, per the SDK's own pda.js: user = ["user", authority, subAccount u16 LE],
   userStats = ["user_stats", authority]. Deriving them here proves the bundle
   points at the VELOCITY program — a Drift-derived address would be a
   different key for the same wallet. */
const program = new sdk.PublicKey(sdk.VELOCITY_PROGRAM_ID);
const userSeed = sdk.PublicKey.findProgramAddressSync(
  [Buffer.from('user'), owner.toBuffer(), new sdk.BN(0).toArrayLike(Buffer, 'le', 2)], program)[0].toString();
const statsSeed = sdk.PublicKey.findProgramAddressSync(
  [Buffer.from('user_stats'), owner.toBuffer()], program)[0].toString();
t('the user PDA comes from ["user", authority, subAccount u16 LE] on the Velocity program',
  userSeed === userPda.toString(), `${userSeed} vs ${userPda?.toString()}`);
t('the userStats PDA comes from ["user_stats", authority] on the Velocity program',
  statsSeed === statsPda.toString(), `${statsSeed} vs ${statsPda?.toString()}`);

/* ── the transaction the module compiles (minus the signature) ───────────── */
const connection = new sdk.Connection('https://api.mainnet-beta.solana.com', 'confirmed');
const message = new sdk.TransactionMessage({
  payerKey: owner,
  recentBlockhash: '11111111111111111111111111111111',
  instructions: [
    sdk.ComputeBudgetProgram.setComputeUnitLimit({ units: 600_000 }),
    sdk.ComputeBudgetProgram.setComputeUnitPrice({ microLamports: 200 }),
    sdk.ComputeBudgetProgram.setComputeUnitLimit({ units: 200_000 }) // a stand-in for a venue ix
  ]
});
const compiled = message.compileToV0Message([]);
const tx = new sdk.VersionedTransaction(compiled);
const bytes = tx.serialize();
t('the v0 transaction builder used by sendInstructions produces a sendable payload',
  bytes.length > 0 && bytes.length <= 1232, `${bytes.length} bytes`);
t('the compute-budget instructions the module prepends are real instructions',
  compiled.compiledInstructions.length === 3);
t('a connection can be built for the configured RPC (no key required)',
  connection?.rpcEndpoint === 'https://api.mainnet-beta.solana.com');

const failed = rows.filter(([, ok]) => !ok);
console.log(failed.length ? `\n${failed.length} failed` : `\nall ${rows.length} velocity trade checks passed`);
process.exit(failed.length ? 1 : 0);
